const RNG_POLL_INTERVAL_MS = 7_000;   // Phase 60 packs-panel cadence.
// Timer cadence when no box is mid-transition: discovery of external
// settlements (another wallet's sweep, another device's purchase) only.
const IDLE_DISCOVERY_POLL_MS = 35_000;
const ERROR_AUTO_CLEAR_MS = 10_000;
// An already-opened box whose result could not be assembled yet is re-read on this
// beat rather than every poll.
const RESULT_PREFETCH_RETRY_MS = 30_000;
const PENDING_SOURCE = 'lootboxes';
// Audit 224de529: (player, index, betId) are all indexed and one event carries
// every spin; topic0 moved with the reshape. topics[1] is still the player.
const DEGENERETTE_RESOLVED_TOPIC = ethers.id(
  'DegeneretteResolved(address,uint32,uint64,uint256,uint32,bytes)',
).toLowerCase();

function _samePlayerDegeneretteResolution(receipt, player, logIndex = null) {
  const playerTopic = `0x${String(player || '').toLowerCase().replace(/^0x/, '').padStart(64, '0')}`;
  const game = String(CONTRACTS.GAME || '').toLowerCase();
  const settlements = (Array.isArray(receipt?.logs) ? receipt.logs : []).filter((log) => (
    String(log?.address || '').toLowerCase() === game
    && String(log?.topics?.[0] || '').toLowerCase() === DEGENERETTE_RESOLVED_TOPIC
    && String(log?.topics?.[1] || '').toLowerCase() === playerTopic
  ));
  if (settlements.length === 0) return false;
  // A keeper sweep settles bets in the same transaction that opens ordinary
  // (e.g. AFKing) index-zero boxes. When the result's leg position is known,
  // it is a Degenerette child only if it lies inside one of that player's bet
  // settlement windows.
  const position = logIndex == null ? null : Number(logIndex);
  if (position == null || !Number.isInteger(position)) return true;
  return settlements.some((log) => {
    try {
      const own = degeneretteSettlementReceipt(receipt, {
        player,
        index: BigInt(log.topics[2]),
        betId: BigInt(log.topics[3]),
      });
      return (own?.logs ?? []).some((entry) => Number(entry?.index ?? entry?.logIndex) === position);
    } catch (_e) {
      return true;
    }
  });
}

async function _degeneretteChildResultKeys(rows, player) {
  const candidates = (Array.isArray(rows) ? rows : []).filter((row) => (
    Number(row?.index) === 0 && String(row?.transactionHash || '')
  ));
  if (candidates.length === 0) return new Set();
  let provider;
  try {
    const connected = getProvider();
    if (!connected
      && (typeof window === 'undefined' || typeof window.fetch !== 'function')) return new Set();
    provider = permissionlessReadProvider(connected);
  } catch (_e) { return new Set(); }
  if (!provider || typeof provider.getTransactionReceipt !== 'function') return new Set();
  const excluded = new Set();
  await Promise.all(candidates.map(async (row) => {
    try {
      const receipt = await readTransactionReceipt(row.transactionHash, { provider });
      if (_samePlayerDegeneretteResolution(receipt, player, row?.logIndex)) excluded.add(_boxKey(row));
    } catch (_e) {
      // A transient RPC failure must not hide an otherwise actionable result.
    }
  }));
  return excluded;
}

function _readResultCursor(addr) {
  try {
    const raw = typeof localStorage !== 'undefined'
      ? localStorage.getItem(lootboxResultCursorKey(CHAIN.id, addr)) : null;
    if (raw == null || raw === '') return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
  } catch (_e) { return null; }
}

function _writeResultCursor(addr, ord) {
  if (!addr || !Number.isFinite(Number(ord))) return;
  try {
    localStorage.setItem(lootboxResultCursorKey(CHAIN.id, addr), String(Number(ord)));
  } catch (_e) { /* private mode */ }
}

function _boxKey(box) {
  if (box?.resultKey != null && String(box.resultKey)) return String(box.resultKey);
  const index = Number(box?.index);
  return Number.isFinite(index) ? String(index) : '';
}

function _boxOrders(values, fallback = null) {
  const raw = Array.isArray(values) && values.length > 0
    ? values
    : fallback == null ? [] : [fallback];
  const orders = [];
  for (const value of raw) {
    try {
      const order = BigInt(value ?? 0);
      if (order > 0n) orders.push(String(order));
    } catch (_e) { /* old/malformed cache row */ }
  }
  return orders;
}

function _boxStacks(box) {
  const totals = { small: 0, medium: 0, large: 0 };
  const custom = new Map();
  for (const packed of _boxOrders(box?.boxOrders, box?.boxOrder)) {
    let order;
    try { order = decodeBoxOrderForDeployment(packed); } catch (_e) { continue; }
    totals.small += Number(order.small || 0);
    totals.medium += Number(order.medium || 0);
    totals.large += Number(order.large || 0);
    if (Number(order.customCount || 0) > 0 && BigInt(order.customSizeWei || 0) > 0n) {
      const key = String(order.customSizeWei);
      custom.set(key, (custom.get(key) || 0) + Number(order.customCount));
    }
  }
  const price = _boxValuePresentation(box).ticketPriceWei;
  const stacks = [];
  const append = (key, label, count, amountWei, forcedModel = null) => {
    if (!Number.isInteger(count) || count <= 0) return;
    const value = lootboxValuePresentation(amountWei, price);
    stacks.push({
      key,
      label,
      count,
      amountWei: amountWei == null ? null : String(amountWei),
      amountLabel: amountWei == null ? null : `${displayEth(amountWei)} ETH`,
      lootboxValueTone: value.tone,
      lootboxCaseModel: forcedModel || value.model,
      lootboxTicketUnitsLabel: value.unitsLabel,
    });
  };
  append('small', 'SMALL', totals.small, price, 'small');
  append('medium', 'MEDIUM', totals.medium, price == null ? null : price * 5n, 'medium');
  append('large', 'LARGE', totals.large, price == null ? null : price * 25n, 'large');
  for (const [amount, count] of custom) {
    append(`custom:${amount}`, 'CUSTOM', count, BigInt(amount));
  }
  return stacks;
}

function _firstPositiveAmount(...values) {
  for (const value of values) {
    try {
      if (value != null && BigInt(value) > 0n) return String(value);
    } catch (_e) { /* malformed optional source */ }
  }
  return values.find((value) => value != null) ?? null;
}

function _eventOrder(row) {
  const blockNumber = Number(row?.blockNumber ?? row?.block_number);
  const logIndex = Number(row?.logIndex ?? row?.log_index ?? 0);
  if (Number.isFinite(blockNumber)) {
    return blockNumber * 1_000_000 + (Number.isFinite(logIndex) ? logIndex : 0);
  }
  const ord = Number(row?.ord);
  return Number.isFinite(ord) ? ord : null;
}

/**
 * Compatibility fallback for older indexers that exposed an index-0 purchase.
 * Current daily afKing boxes emit only AfkingDelivered + LootBoxOpened, so the
 * authoritative path is `afkingSpendRawWei` from `/lootbox/legs` below.
 */
export function applyAfkingRawPurchaseAmounts(resolvedRows, purchaseItems) {
  const rows = (Array.isArray(resolvedRows) ? resolvedRows : []).map((row) => ({ ...row }));
  const purchases = (Array.isArray(purchaseItems) ? purchaseItems : [])
    .filter((item) => item?.resolvedIndex != null
      && Number(item.resolvedIndex) === 0
      && String(item?.kind || '').toLowerCase() === 'eth')
    .map((item) => {
      try {
        const amountWei = BigInt(item?.costRawWei ?? item?.boxAmountRawWei ?? 0);
        return amountWei > 0n
          ? {
              amountWei: String(amountWei),
              order: _eventOrder(item),
              transactionHash: String(item?.transactionHash || '').toLowerCase(),
              used: false,
            }
          : null;
      } catch (_e) {
        return null;
      }
    })
    .filter((item) => item && item.order != null)
    .sort((a, b) => a.order - b.order);

  const openings = rows
    .map((row, index) => ({ row, index, order: _eventOrder(row) }))
    .filter(({ row, order }) => Number(row?.index) === 0
      && row?.rawPurchaseAmountWei == null
      && order != null)
    .sort((a, b) => a.order - b.order);

  for (const opening of openings) {
    const openingHash = String(opening.row?.transactionHash || '').toLowerCase();
    let match = purchases.find((purchase) => (
      !purchase.used && openingHash && purchase.transactionHash === openingHash
    ));
    if (!match) {
      for (const purchase of purchases) {
        if (!purchase.used && purchase.order <= opening.order
          && (!match || purchase.order > match.order)) match = purchase;
      }
    }
    if (!match) continue;
    match.used = true;
    rows[opening.index] = {
      ...opening.row,
      amountWei: match.amountWei,
      rawPurchaseAmountWei: match.amountWei,
    };
  }
  return rows;
}

function _boxLabel(box, upper = false) {
  const label = 'Luckbox';
  return upper ? label.toUpperCase() : label;
}

function _boxAmountLabel(box) {
  try {
    const raw = _boxDisplayAmount(box);
    if (raw <= 0n) return null;
    const rendered = displayEth(raw, 4);
    const amount = String(rendered).includes('.')
      ? String(rendered).replace(/0+$/, '').replace(/\.$/, '')
      : String(rendered);
    return `${amount} ETH`;
  } catch (_e) {
    return null;
  }
}

function _boxDisplayAmount(box) {
  let fallback = 0n;
  try { fallback = BigInt(box?.amountWei ?? 0); } catch (_e) { /* old/malformed cache row */ }
  const orders = _boxOrders(box?.boxOrders, box?.boxOrder);
  // Count and purchase value must come from the same immutable order. The
  // result feed can supply a single smaller roll from a six-box purchase;
  // that reward amount is not the value of the purchased batch.
  if (orders.length === 0) return fallback;
  try {
    const price = BigInt(box?.ticketPriceWei ?? 0);
    let total = 0n;
    for (const packed of orders) {
      const order = decodeBoxOrderForDeployment(packed);
      // Presets need their purchase-time price. Never reprice a saved order
      // against today's ticket price; custom amounts are encoded in the order.
      if (price <= 0n && (order.small || order.medium || order.large)) return fallback;
      total += boxOrderCostFromPriceWei(price, packed);
    }
    return total > 0n ? total : fallback;
  } catch (_e) { return fallback; }
}

function _boxValuePresentation(box) {
  return box?.ticketPriceWei == null
    ? lootboxValuePresentation(_boxDisplayAmount(box))
    : lootboxValuePresentation(_boxDisplayAmount(box), box.ticketPriceWei);
}

function _readRevealed(addr) {
  try {
    const raw = typeof localStorage !== 'undefined'
      ? localStorage.getItem(revealedBoxesKey(CHAIN.id, addr)) : null;
    const parsed = raw ? JSON.parse(raw) : [];
    return new Set(Array.isArray(parsed) ? parsed.map(String) : []);
  } catch (_e) {
    return new Set();
  }
}

function _markRevealed(addr, key) {
  if (!addr) return;
  try {
    const seen = _readRevealed(addr);
    seen.add(String(key));
    localStorage.setItem(revealedBoxesKey(CHAIN.id, addr), JSON.stringify([...seen]));
  } catch (_e) { /* private mode: replay may reappear after refresh */ }
}

function _unmarkRevealed(addr, key) {
  if (!addr || !key) return;
  try {
    const seen = _readRevealed(addr);
    if (!seen.delete(String(key))) return;
    if (seen.size === 0) localStorage.removeItem(revealedBoxesKey(CHAIN.id, addr));
    else localStorage.setItem(revealedBoxesKey(CHAIN.id, addr), JSON.stringify([...seen]));
  } catch (_e) { /* private mode */ }
}

function _boxDismissKey(box) {
  const key = _boxKey(box);
  const hashes = [...new Set([
    ...(Array.isArray(box?.transactionHashes) ? box.transactionHashes : []),
    box?.transactionHash,
  ].filter(Boolean).map((hash) => String(hash).toLowerCase()))].sort();
  return hashes.length > 0
    // Keep one purchase identity while it moves from the optimistic
    // `submitted:<hash>` placeholder to its mined RNG index. Otherwise CLEAR
    // tombstones the placeholder and confirmation immediately republishes the
    // exact same purchase under a different key.
    ? `lootbox:purchases:${hashes.join(',')}`
    : `lootbox:${key}`;
}

function _readPending(addr) {
  try {
    const raw = typeof localStorage !== 'undefined'
      ? localStorage.getItem(pendingBoxesKey(CHAIN.id, addr)) : null;
    const parsed = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(parsed)) return [];
    const revealed = _readRevealed(addr);
    return parsed
      .filter((e) => e && (Number.isFinite(Number(e.index)) || e.resultKey != null))
      .filter((e) => !revealed.has(_boxKey(e)))
      .map((e) => ({
        index: e.index == null || !Number.isFinite(Number(e.index)) ? null : Number(e.index),
        resultKey: e.resultKey == null ? null : String(e.resultKey),
        transactionHash: e.transactionHash == null ? null : String(e.transactionHash),
        resultTransactionHash: e.resultTransactionHash == null
          ? null
          : String(e.resultTransactionHash),
        blockNumber: Number.isFinite(Number(e.blockNumber)) ? Number(e.blockNumber) : null,
        transactionHashes: [...new Set([
          ...(Array.isArray(e.transactionHashes) ? e.transactionHashes : []),
          e.transactionHash,
        ].filter(Boolean).map((hash) => String(hash).toLowerCase()))],
        boxOrders: _boxOrders(e.boxOrders, e.boxOrder),
        ord: Number.isFinite(Number(e.ord)) ? Number(e.ord) : null,
        day: e.day != null ? Number(e.day) : null,
        // Old cache rows predate this flag and were all receipt-sourced.
        // DB-discovered rows persist false so a stale API row cannot become a
        // trusted receipt row merely because the page refreshed.
        fromReceipt: e.fromReceipt !== false,
        createdAt: Number.isFinite(Number(e.createdAt)) ? Number(e.createdAt) : null,
        amountWei: e.amountWei == null ? null : String(e.amountWei),
        ticketPriceWei: e.ticketPriceWei == null ? null : String(e.ticketPriceWei),
        hasLootboxLeg: Boolean(e.hasLootboxLeg),
        optimistic: Boolean(e.optimistic),
        resultSyncing: Boolean(e.resultSyncing),
        ready: Boolean(!e.resultSyncing && (e.ready || e.resolved)),
        resolved: Boolean(e.resolved),
      }));
  } catch (_e) {
    return [];
  }
}

function _writePending(addr, entries) {
  try {
    if (typeof localStorage === 'undefined') return;
    const key = pendingBoxesKey(CHAIN.id, addr);
    if (!entries || entries.length === 0) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify(entries.map((e) => ({
      index: e.index == null || !Number.isFinite(Number(e.index)) ? null : Number(e.index),
      resultKey: e.resultKey ?? null,
      transactionHash: e.transactionHash ?? null,
      resultTransactionHash: e.resultTransactionHash ?? null,
      blockNumber: Number.isFinite(Number(e.blockNumber)) ? Number(e.blockNumber) : null,
      transactionHashes: [...new Set([
        ...(Array.isArray(e.transactionHashes) ? e.transactionHashes : []),
        e.transactionHash,
      ].filter(Boolean).map((hash) => String(hash).toLowerCase()))],
      boxOrders: _boxOrders(e.boxOrders, e.boxOrder),
      ord: Number.isFinite(Number(e.ord)) ? Number(e.ord) : null,
      day: e.day,
      fromReceipt: e.fromReceipt !== false,
      createdAt: Number.isFinite(Number(e.createdAt)) ? Number(e.createdAt) : null,
      amountWei: e.amountWei == null ? null : String(e.amountWei),
      ticketPriceWei: e.ticketPriceWei == null ? null : String(e.ticketPriceWei),
      hasLootboxLeg: Boolean(e.hasLootboxLeg),
      optimistic: Boolean(e.optimistic),
      resultSyncing: Boolean(e.resultSyncing),
      ready: Boolean(e.ready),
      resolved: Boolean(e.resolved),
    }))));
  } catch (_e) { /* quota / private mode — session-only tracking */ }
}

/**
 * Collapse the durable per-leg result feed into one resolved row per opening
 * transaction. Normal boxes use their shared RNG index; AFKing auto-opens all
 * use index zero, so their transaction hash is the only collision-free key.
 */
export function resolvedBoxRowsFromLegs(items, player) {
  const wantPlayer = String(player || '').toLowerCase();
  const rows = new Map();
  for (const item of Array.isArray(items) ? items : []) {
    if (String(item?.player || '').toLowerCase() !== wantPlayer) continue;
    const legType = String(item?.legType || '');
    if (!['opened', 'flipOpened', 'spin'].includes(legType)) continue;
    // Older feeds can assign every BoxSpin the transaction's opening index.
    // Biggest-card bounties are owned by Degenerette, never a pending Luckbox.
    if (legType === 'spin'
      && ['record', 'unknown_3'].includes(String(item?.spin?.spinType || '').toLowerCase())) continue;
    // The normal player feed cannot infer an index for BoxSpin. Treating its
    // null as Number(null) === 0 would fabricate an AFKing result; only an
    // exact-index response is allowed to promote a spin-only settlement.
    if (legType === 'spin' && item?.lootboxIndex == null) continue;
    const index = Number(item?.lootboxIndex);
    if (!Number.isFinite(index) || index < 0) continue;
    const transactionHash = String(item?.transactionHash || '').toLowerCase();
    if (index === 0 && !transactionHash) continue;
    const resultKey = index === 0 ? `tx:${transactionHash}` : String(index);
    const ord = Number(item?.ord ?? item?.logIndex ?? 0);
    const prior = rows.get(resultKey);
    let afkingSpendRawWei = prior?.rawPurchaseAmountWei ?? null;
    try {
      const rawDelivery = BigInt(item?.afkingSpendRawWei ?? 0);
      if (index === 0 && rawDelivery > 0n) afkingSpendRawWei = String(rawDelivery);
    } catch (_e) { /* malformed optional API enrichment */ }
    if (!prior || ord > prior.ord) {
      rows.set(resultKey, {
        index,
        resultKey,
        transactionHash: transactionHash || null,
        // The SETTLEMENT transaction, distinct from the purchase hash a
        // receipt-discovered box carries. This row exists because a leg proved
        // the open, so the opening tx is already known — replay must reuse this
        // exact key instead of re-deriving one from a fresh anchor lookup that
        // can miss and leave the box latched resolved with nothing to show.
        resultTransactionHash: transactionHash || null,
        blockNumber: item?.blockNumber ?? null,
        logIndex: item?.logIndex ?? null,
        // Daily afKing boxes do not emit LootBoxBuy. The indexer correlates
        // their raw `AfkingDelivered.weiIn` onto the settlement leg; keep it
        // separate so it also repairs an older cached EV-scaled chip amount.
        rawPurchaseAmountWei: afkingSpendRawWei,
        amountWei: String(
          afkingSpendRawWei
          ?? item?.rewardData?.amount
          ?? item?.boxAmountRawWei
          ?? item?.amount
          ?? 0,
        ),
        day: null,
        ready: true,
        resolved: true,
        opening: false,
        ord,
        hasLootboxLeg: true,
      });
    }
  }
  return [...rows.values()].sort((a, b) => b.ord - a.ord || b.index - a.index);
}

function _mergeLegRows(...groups) {
  const merged = new Map();
  for (const item of groups.flatMap((group) => Array.isArray(group) ? group : [])) {
    const key = item?.uid
      || `${String(item?.transactionHash || '').toLowerCase()}:${Number(item?.logIndex ?? -1)}:${item?.legType || ''}`;
    merged.set(key, item);
  }
  return [...merged.values()];
}

// Every physical box settles with exactly one event: LootBoxOpened, or BoxSpin
// when its roll is a spin (craps-pass rolls still emit LootBoxOpened; their
// passes ride one LootBoxCrapsPasses per entry). Record-bounty spins are not boxes.
function _settledBoxCount(legs) {
  return (Array.isArray(legs) ? legs : []).filter((leg) => leg?.legType === 'opened'
    || (leg?.legType === 'spin'
      && !['record', 'unknown_3'].includes(String(leg?.spinType ?? leg?.spin?.spinType ?? '').toLowerCase())))
    .length;
}

/** Boxes the stored purchase order says this entry holds; 0 when unknown. */
function _expectedBoxCount(box) {
  let count = 0;
  for (const packed of _boxOrders(box?.boxOrders, box?.boxOrder)) {
    let order;
    try { order = decodeBoxOrderForDeployment(packed); } catch (_e) { continue; }
    count += Number(order.quantity || 0)
      || Number(order.small || 0) + Number(order.medium || 0) + Number(order.large || 0)
        + Number(order.customCount || 0);
  }
  return count;
}

// A 200-row feed window or a rate-limited scan can return part of one
// settlement. Revealing that fragment showed one box of a 14-box order and
// marked the whole entry seen (2026-10-18), so a short read is not a result.
function _missingBoxes(box, legs) {
  const expected = _expectedBoxCount(box);
  return expected > 0 && _settledBoxCount(legs) < expected;
}
// A count that never completes (a leg shape this build cannot classify) must
// not strand the box: after this long short, reveal what the chain gave.
const SHORT_RESULT_GRACE_MS = 90_000;

function _needsReceiptRecovery(legs) {
  if (!Array.isArray(legs) || legs.length === 0) return true;
  return legs.some((leg) => {
    if (leg?.legType !== 'opened') return false;
    let flip = 0n;
    try { flip = BigInt(leg.flip ?? 0); } catch (_e) { /* malformed feed value */ }
    return Number(leg.wholeTickets ?? 0) === 0 && flip === 0n;
  });
}

/**
 * LootBoxOpened is the transaction anchor, not necessarily the prize: current
 * boxes can pay entirely through a same-transaction aggregate event. If a feed
 * projection or receipt decoder omits that companion event, do not consume the
 * pending box until the normalized legs can produce a real reveal card;
 * otherwise the overlay turns the cardless anchor into its legacy
 * `0 TICKETS · 0 FLIP` fallback and retires it.
 */
export function lootboxResultLegsReadyForReveal(legs) {
  if (!Array.isArray(legs) || legs.length === 0) return false;
  return legs.some((leg) => {
    if (!leg) return false;
    if (leg.legType !== 'opened') return true;
    let flip = 0n;
    try { flip = BigInt(leg.flip ?? 0); } catch (_e) { /* malformed feed value */ }
    return Number(leg.wholeTickets ?? 0) > 0
      || Number(leg.futureTickets ?? 0) > 0
      || flip > 0n
      || Number(leg.crapsNormalPasses ?? 0) > 0
      || Number(leg.crapsHighPasses ?? 0) > 0;
  });
}

class AppBoxStrip extends HTMLElement {
  #unsubs = [];
  #initialized = false;
  #pollHandle = null;
  #pollBusy = false;
  // Resolves when the cycle currently running finishes. The address
  // subscription starts a cycle of its own, so a caller that needs settled
  // state has to wait for that one rather than race its 7s successor.
  #pollInFlight = null;
  // Box key -> when its settled result was first read short of the order's count.
  #shortResultSince = new Map();
  #lastPollCycleAt = 0;
  #errorTimer = null;
  #docListener = null;
  #submittedListener = null;
  #failedListener = null;
  #revealQueuedListener = null;
  #revealCompleteListener = null;
  #revealAbortListener = null;
  // API history can contain legacy purchase rows whose result never received
  // an index-bearing settlement anchor. Once the authoritative on-chain slot
  // confirms one of those indexes is empty, do not probe/promote it every 7s.
  #emptyIndexes = new Set();
  // A queued presentation leaves the durable receipt in storage until the
  // overlay actually completes. Hiding it only in-memory means an abort or a
  // refresh can restore the result instead of permanently eating the box.
  #activeRevealKeys = new Set();
  #purchaseReceipts = new Map();
  // Once a background sync has assembled a complete result, hold those exact
  // legs until the pending action consumes them. This prevents a transient API
  // miss between the poll and the click from dropping the row back into sync.
  #resolvedLegCache = new Map();
  // One result read per box: the background prefetch and an OPEN click share it.
  #resolvedLegReads = new Map();
  // When each already-opened box was last prefetched, so an incomplete result is
  // retried on a slower beat than the seven-second poll.
  #prefetchAttemptAt = new Map();
  // The player's newest legs page, as the poll cycle last read it. In chain mode it
  // is exactly what a per-box lookup would fetch again (same RPC, same window).
  #recentLegRows = { owner: null, items: [] };
  #prefetchInFlight = null;
  // [{index, day, ready, opening, fromReceipt, createdAt}]
  #boxes = [];
  #addr = null;
  #clearGeneration = 0;

  // Snapshot both owner cleanup and fullscreen Clear. The latter can run
  // while every box is hidden behind an active reveal and no owner row exists.
  #workToken() {
    return `${this.#addr}:${this.#clearGeneration}:${getPendingClearGeneration()}`;
  }

  connectedCallback() {
    if (this.#initialized) return;
    this.#initialized = true;
    this.#renderShell();
    this.#wireStore();
    this.#wireDocEvents();
    this.#startPolling();
  }

  disconnectedCallback() {
    // In-flight API reads may settle after detachment. Clearing the owner makes
    // their address-stability guard abort before a stale strip republishes the
    // shared pending-action source.
    this.#clearGeneration += 1;
    this.#addr = null;
    this.#boxes = [];
    this.#emptyIndexes.clear();
    this.#activeRevealKeys.clear();
    this.#purchaseReceipts.clear();
    this.#clearResultReads();
    if (typeof this.#pollHandle === 'function') {
      try { this.#pollHandle(); } catch (_) { /* defensive */ }
      this.#pollHandle = null;
    }
    if (this.#errorTimer != null) {
      try { clearTimeout(this.#errorTimer); } catch (_) { /* defensive */ }
      this.#errorTimer = null;
    }
    if (this.#docListener && typeof document !== 'undefined'
      && typeof document.removeEventListener === 'function') {
      try { document.removeEventListener('app-decimator:tx-confirmed', this.#docListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener('app-pass:tx-confirmed', this.#docListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener('app-decimator:tx-submitted', this.#submittedListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener('app-decimator:tx-failed', this.#failedListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener(LOOTBOX_REVEAL_QUEUED_EVENT, this.#revealQueuedListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener(LOOTBOX_REVEAL_COMPLETE_EVENT, this.#revealCompleteListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener(LOOTBOX_REVEAL_ABORT_EVENT, this.#revealAbortListener); }
      catch (_) { /* defensive */ }
    }
    this.#docListener = null;
    this.#submittedListener = null;
    this.#failedListener = null;
    this.#revealQueuedListener = null;
    this.#revealCompleteListener = null;
    this.#revealAbortListener = null;
    clearPendingActions(PENDING_SOURCE);
    for (const u of this.#unsubs) {
      try { u(); } catch (_e) { /* defensive */ }
    }
    this.#unsubs = [];
  }

  #renderShell() {
    if (this.getAttribute?.('tray-only') != null) {
      // Stay connected for receipt listening, durable discovery, readiness
      // probes, and action publishing. The reveal tray is the sole visible UI.
      this.innerHTML = '';
      return;
    }
    this.innerHTML = `
      <div class="bxs-strip" data-bind="bxs-strip" hidden>
        <span class="bxs-label">YOUR BOXES</span>
        <div class="bxs-chips" data-bind="bxs-chips"></div>
        <div class="bxs-error" data-bind="bxs-error" hidden role="alert"></div>
      </div>
    `;
  }

  #bind(name) { return this.querySelector(`[data-bind="${name}"]`); }

  #wireStore() {
    const u = subscribe('connected.address', (addr) => {
      this.#addr = addr ? String(addr).toLowerCase() : null;
      this.#emptyIndexes.clear();
      this.#activeRevealKeys.clear();
      this.#purchaseReceipts.clear();
      this.#clearResultReads();
      this.#boxes = this.#addr
        ? _readPending(this.#addr).map((e) => ({
            ...e,
            ready: Boolean(!e.resultSyncing && (e.ready || e.resolved)),
            resolved: Boolean(e.resolved),
            opening: false,
          }))
        : [];
      // Older clients could persist a late poll's copy of an already-revealed
      // box. Repair that cache before Pending paints, even with the RPC offline.
      if (this.#addr) _writePending(this.#addr, this.#boxes);
      this.#render();
      // The DB is the durable inventory and result ledger; localStorage only
      // bridges the short purchase-to-indexing window.
      if (this.#addr) this.#runPollCycle();
    });
    this.#unsubs.push(u);
  }

  #wireDocEvents() {
    if (typeof document === 'undefined' || typeof document.addEventListener !== 'function') return;
    this.#submittedListener = (e) => {
      const detail = e?.detail || {};
      const player = String(detail.player || '').toLowerCase();
      const transactionHash = String(detail.transactionHash || '').toLowerCase();
      if (!this.#addr || player !== this.#addr || !transactionHash) return;
      const resultKey = `submitted:${transactionHash}`;
      if (this.#boxes.some((box) => _boxKey(box) === resultKey)) return;
      this.#boxes.push({
        index: null,
        resultKey,
        transactionHash,
        transactionHashes: [transactionHash],
        boxOrders: _boxOrders(null, detail.boxOrder),
        day: null,
        ready: false,
        resolved: false,
        opening: false,
        fromReceipt: true,
        optimistic: true,
        createdAt: Date.now(),
        amountWei: (() => {
          try {
            return String(BigInt(detail.lootBoxAmountWei ?? 0));
          } catch (_e) { return null; }
        })(),
        hasLootboxLeg: (() => {
          try { return BigInt(detail.lootBoxAmountWei ?? 0) > 0n; } catch (_e) { return false; }
        })(),
        ticketPriceWei: detail.ticketPriceWei == null
          ? null
          : String(detail.ticketPriceWei),
      });
      _writePending(this.#addr, this.#boxes);
      this.#render();
    };
    this.#failedListener = (e) => {
      const detail = e?.detail || {};
      const player = String(detail.player || '').toLowerCase();
      const transactionHash = String(detail.transactionHash || '').toLowerCase();
      if (!this.#addr || player !== this.#addr || !transactionHash) return;
      this.#removeBox(`submitted:${transactionHash}`);
    };
    this.#docListener = (e) => {
      const detail = e?.detail || {};
      const boxes = detail.boxes;
      if (!this.#addr) return;
      const player = String(e?.detail?.player || '').toLowerCase();
      if (player && player !== this.#addr) return;
      const submittedHash = String(
        e?.detail?.submittedTransactionHash || e?.detail?.transactionHash || '',
      ).toLowerCase();
      const submittedKey = submittedHash ? `submitted:${submittedHash}` : '';
      const submitted = submittedKey
        ? this.#boxes.find((box) => _boxKey(box) === submittedKey)
        : null;
      if (!Array.isArray(boxes) || boxes.length === 0) {
        if (submitted) {
          submitted.optimistic = false;
          submitted.createdAt = Date.now();
          if (detail.ticketPriceWei != null) {
            submitted.ticketPriceWei = String(detail.ticketPriceWei);
          }
          _writePending(this.#addr, this.#boxes);
          this.#render();
          this.#runPollCycle();
        }
        return;
      }
      if (submittedKey) {
        this.#boxes = this.#boxes.filter((box) => _boxKey(box) !== submittedKey);
      }
      for (const b of boxes) {
        const index = Number(b?.index);
        if (!Number.isFinite(index)) continue;
        // Index 0 is an afKing box: stamped daily, opened by the mineFlip sweep, never a buy.
        if (index === 0) continue;
        const incomingHash = String(
          detail.transactionHash || submitted?.transactionHash || submittedHash || '',
        ).toLowerCase();
        const incomingBoxOrders = _boxOrders(b?.boxOrders, b?.boxOrder ?? detail.boxOrder);
        const existing = this.#boxes.find((x) => _boxKey(x) === String(index));
        if (existing) {
          // Several purchases can share one RNG index. That is one open action,
          // not a duplicate. Merge later purchases into the batch while using
          // their tx hashes to keep repeated browser events idempotent.
          const knownHashes = new Set([
            ...(Array.isArray(existing.transactionHashes) ? existing.transactionHashes : []),
            existing.transactionHash,
          ].filter(Boolean).map((hash) => String(hash).toLowerCase()));
          const addsNewLeg = Boolean(b?.hasLootboxLeg) && !existing.hasLootboxLeg;
          const addsPurchase = incomingHash ? !knownHashes.has(incomingHash) : addsNewLeg;
          if (addsPurchase) _unmarkRevealed(this.#addr, String(index));
          if (addsPurchase && b?.amountWei != null) {
            try {
              existing.amountWei = String(
                BigInt(existing.amountWei ?? 0) + BigInt(b.amountWei),
              );
            } catch (_e) { /* retain the already-known amount */ }
          }
          existing.hasLootboxLeg ||= Boolean(b?.hasLootboxLeg);
          existing.fromReceipt = true;
          existing.optimistic = false;
          existing.createdAt = Date.now();
          if (incomingHash) {
            knownHashes.add(incomingHash);
            existing.transactionHash ||= incomingHash;
          }
          existing.transactionHashes = [...knownHashes];
          if (addsPurchase && incomingBoxOrders.length > 0) {
            existing.boxOrders = [
              ..._boxOrders(existing.boxOrders, existing.boxOrder),
              ...incomingBoxOrders,
            ];
          } else if (_boxOrders(existing.boxOrders, existing.boxOrder).length === 0
            && submitted?.boxOrders?.length > 0) {
            existing.boxOrders = _boxOrders(submitted.boxOrders);
          }
          if (b?.ticketPriceWei != null || detail.ticketPriceWei != null) {
            existing.ticketPriceWei = String(b?.ticketPriceWei ?? detail.ticketPriceWei);
          }
          this.#emptyIndexes.delete(index);
          continue;
        }
        // CLEAR historically marked only the shared RNG index. A newly mined
        // purchase can legitimately join that same still-open batch, so its
        // receipt must retire the stale presentation marker.
        _unmarkRevealed(this.#addr, String(index));
        this.#boxes.push({
          index,
          resultKey: String(index),
          transactionHash: incomingHash || null,
          transactionHashes: incomingHash ? [incomingHash] : [],
          boxOrders: incomingBoxOrders.length > 0
            ? incomingBoxOrders
            : _boxOrders(submitted?.boxOrders, submitted?.boxOrder),
          day: b?.day != null ? Number(b.day) : null,
          ready: false,
          resolved: false,
          opening: false,
          fromReceipt: true,
          optimistic: false,
          createdAt: Date.now(),
          amountWei: b?.amountWei == null && boxes.length === 1
            ? (() => {
                try {
                  return String(BigInt(detail.lootBoxAmountWei ?? 0));
                } catch (_e) { return null; }
              })()
            : b?.amountWei == null ? null : String(b.amountWei),
          hasLootboxLeg: Boolean(b?.hasLootboxLeg),
          ticketPriceWei: b?.ticketPriceWei == null
            ? detail.ticketPriceWei == null
              ? submitted?.ticketPriceWei ?? null
              : String(detail.ticketPriceWei)
            : String(b.ticketPriceWei),
        });
        this.#emptyIndexes.delete(index);
      }
      _writePending(this.#addr, this.#boxes);
      this.#render();
      this.#runPollCycle();
    };
    document.addEventListener('app-decimator:tx-submitted', this.#submittedListener);
    document.addEventListener('app-decimator:tx-failed', this.#failedListener);
    document.addEventListener('app-decimator:tx-confirmed', this.#docListener);
    document.addEventListener('app-pass:tx-confirmed', this.#docListener);

    // A direct Degenerette settlement and the durable box feed can discover the
    // same index-zero box independently. Hide that exact tray copy while the
    // presentation is active, but do not tombstone its durable receipt until
    // the player completes it; an aborted overlay must restore the action.
    this.#revealQueuedListener = (event) => {
      const detail = event?.detail;
      const address = String(detail?.address || '').toLowerCase();
      const key = String(detail?.key || '');
      if (!address || !key) return;
      if (address === this.#addr) {
        this.#activeRevealKeys.add(key);
        const box = this.#boxes.find((row) => _boxKey(row) === key);
        if (box) box.opening = true;
        if (this.#addr) _writePending(this.#addr, this.#boxes);
        this.#render();
      }
    };
    this.#revealCompleteListener = (event) => {
      const detail = event?.detail;
      const address = String(detail?.address || '').toLowerCase();
      const key = String(detail?.key || '');
      if (!address || !key) return;
      _markRevealed(address, key);
      if (address === this.#addr) {
        this.#activeRevealKeys.delete(key);
        this.#removeBox(key);
      }
    };
    this.#revealAbortListener = (event) => {
      for (const release of Array.isArray(event?.detail?.releases)
        ? event.detail.releases : []) {
        if (String(release?.address || '').toLowerCase() !== this.#addr) continue;
        const key = String(release?.key || '');
        this.#activeRevealKeys.delete(key);
        const box = this.#boxes.find((row) => _boxKey(row) === key);
        if (box) box.opening = false;
      }
      if (this.#addr) {
        _writePending(this.#addr, this.#boxes);
        this.#render();
      }
    };
    document.addEventListener(LOOTBOX_REVEAL_QUEUED_EVENT, this.#revealQueuedListener);
    document.addEventListener(LOOTBOX_REVEAL_COMPLETE_EVENT, this.#revealCompleteListener);
    document.addEventListener(LOOTBOX_REVEAL_ABORT_EVENT, this.#revealAbortListener);
  }

  // -------------------------------------------------------------------------
  // RNG polling — 7s tick over not-yet-ready boxes.
  // -------------------------------------------------------------------------

  #startPolling() {
    // The 7s cadence exists to catch a box mid-transition (waiting for RNG,
    // opening, or waiting for the indexer to seat its result). With nothing in
    // flight the two forced 200-row feed reads are pure discovery — someone
    // else's sweep or a purchase from another device — and a slow cadence
    // serves that. Event-driven refreshes (purchase, reveal, TX) stay
    // immediate; only the timer is gated.
    this.#pollHandle = registerComponentPoll(() => {
      const hot = this.#boxes.some((box) => (
        (!box.ready && !box.resolved) || box.resultSyncing || box.opening
      ));
      if (!hot && Date.now() - this.#lastPollCycleAt < IDLE_DISCOVERY_POLL_MS) return undefined;
      return this.#runPollCycle();
    }, RNG_POLL_INTERVAL_MS, { owner: this });
  }

  async #readPurchaseKinds(box, owner) {
    const hashes = [...new Set([
      ...(Array.isArray(box?.transactionHashes) ? box.transactionHashes : []),
      box?.transactionHash,
    ].filter(Boolean).map((hash) => String(hash).toLowerCase()))];
    let found = null;
    for (const hash of hashes) {
      const cacheKey = `${owner}:${box.index}:${hash}`;
      let receipt = this.#purchaseReceipts.get(cacheKey);
      if (receipt === undefined) {
        receipt = await readLootboxPurchaseReceipt({
          transactionHash: hash,
          player: owner,
          lootboxIndex: box.index,
        });
        if (receipt) this.#purchaseReceipts.set(cacheKey, receipt);
      }
      if (!receipt) continue;
      found ||= { hasLootboxLeg: false, amountWei: 0n };
      found.hasLootboxLeg ||= Boolean(receipt.hasLootboxLeg);
      found.amountWei += BigInt(receipt.amountWei ?? 0);
    }
    return found;
  }

  async #runPollCycle() {
    if (this.#pollBusy) return;
    let settle;
    this.#pollInFlight = new Promise((resolve) => { settle = resolve; });
    if (typeof document !== 'undefined'
      && document.visibilityState
      && document.visibilityState !== 'visible') return;
    if (!this.#addr) return;
    this.#pollBusy = true;
    this.#lastPollCycleAt = Date.now();
    const owner = this.#addr;
    const token = this.#workToken();
    try {
      // Purchases tell us about boxes still waiting for RNG. Settlement legs
      // are the durable source for completed boxes and full BoxSpin reels.
      // Keep the calls independent: an old/mid-deploy API can serve one route
      // correctly while the other is temporarily unavailable.
      const [feedCall, legsCall] = await Promise.allSettled([
        // This seven-second loop detects a one-way indexing transition. A
        // transaction-triggered cycle can run less than a second before the
        // indexer catches up, so completed render-wave responses are stale by
        // definition here. In-flight requests remain shared.
        fetchJSON(
          `/lootbox/feed?limit=200&player=${encodeURIComponent(owner)}${CHAIN.readMode === 'chain' ? '&recover=1' : ''}`,
          { force: true },
        ),
        fetchJSON(
          `/lootbox/legs?limit=200&player=${encodeURIComponent(owner)}`,
          { force: true },
        ),
      ]);
      if (this.#addr !== owner || token !== this.#workToken()) return;
      const response = feedCall.status === 'fulfilled' ? feedCall.value : null;
      const legsResponse = legsCall.status === 'fulfilled' ? legsCall.value : null;
      if (legsResponse) {
        this.#recentLegRows = {
          owner,
          items: Array.isArray(legsResponse.items) ? legsResponse.items : [],
        };
      }
      const revealed = _readRevealed(owner);
      const feedRows = new Map();
      for (const item of Array.isArray(response?.items) ? response.items : []) {
        // Client-side filtering is deliberate. It keeps the wallet view honest
        // against older API deployments that accepted `player` but ignored it.
        if (String(item?.player || '').toLowerCase() !== owner) continue;
        const index = Number(item?.resolvedIndex);
        if (!Number.isFinite(index) || index <= 0) continue;
        const row = feedRows.get(index) || {
          index, day: null, ready: false, resolved: false, opening: false,
          fromReceipt: false, transactionHash: null, transactionHashes: [],
          amountWei: '0', hasLootboxLeg: false,
        };
        row.transactionHash = String(item?.transactionHash || row.transactionHash || '').toLowerCase() || null;
        if (row.transactionHash && !row.transactionHashes.includes(row.transactionHash)) {
          row.transactionHashes.push(row.transactionHash);
        }
        try {
          // costRawWei is the pre-boon spend. The credited box amount is what
          // the deterministic BoxSpin id commits to, so retain it when the
          // feed supplies it and use cost only for older API rows.
          row.amountWei = String(
            BigInt(row.amountWei) + BigInt(item?.boxAmountRawWei ?? item?.costRawWei ?? 0),
          );
        }
        catch (_e) { /* retain the sum recovered so far */ }
        row.hasLootboxLeg = true;
        const resultTypes = new Set((Array.isArray(item?.results) ? item.results : [])
          .map((result) => String(result?.rewardType || '')));
        row.hasLootboxLeg ||= resultTypes.has('opened') || resultTypes.has('flipOpened');
        row.ready ||= Boolean(item?.rngReady);
        row.resolved ||= Boolean(item?.opened)
          || resultTypes.has('opened')
          || resultTypes.has('flipOpened');
        if (row.resolved) row.ready = true;
        feedRows.set(index, row);
      }

      const local = new Map(this.#boxes.map((box) => [_boxKey(box), box]));
      const tracked = new Set(local.keys());
      const allResolvedRows = applyAfkingRawPurchaseAmounts(
        resolvedBoxRowsFromLegs(legsResponse?.items, owner),
        response?.items,
      );
      const priorCursor = _readResultCursor(owner);
      const newlyDiscoveredRows = priorCursor == null
        ? []
        : allResolvedRows.filter((row) => Number(row.ord) > priorCursor);
      // Degenerette's owning panel reconstructs the awarding spin and appends
      // its child Luckbox after that parent. The generic index-zero result
      // watcher can otherwise observe the shared receipt first and publish the
      // child independently, reversing causal reveal order. Receipt topics are
      // authoritative and keep unrelated AFKing index-zero results eligible.
      const rowsNeedingCausalClassification = allResolvedRows.filter((row) => (
        tracked.has(_boxKey(row)) || newlyDiscoveredRows.includes(row)
      ));
      const degeneretteChildKeys = await _degeneretteChildResultKeys(
        rowsNeedingCausalClassification,
        owner,
      );
      if (this.#addr !== owner || token !== this.#workToken()) return;
      for (const key of degeneretteChildKeys) local.delete(key);
      const resolvedRows = allResolvedRows.filter(
        (row) => !degeneretteChildKeys.has(_boxKey(row)),
      );
      const resolvedByKey = new Map(resolvedRows.map((row) => [_boxKey(row), row]));

      // If receipt parsing could not recover the index, the indexed purchase
      // later promotes the exact submitted-hash placeholder without touching
      // any other box already in Pending.
      for (const feed of feedRows.values()) {
        if (!feed.transactionHash) continue;
        const submittedKey = `submitted:${feed.transactionHash}`;
        const submitted = local.get(submittedKey);
        if (!submitted) continue;
        local.delete(submittedKey);
        local.set(String(feed.index), {
          ...submitted,
          ...feed,
          resultKey: String(feed.index),
          optimistic: false,
          fromReceipt: true,
          amountWei: submitted.amountWei ?? feed.amountWei,
          hasLootboxLeg: Boolean(submitted.hasLootboxLeg || feed.hasLootboxLeg),
        });
      }
      const newestOrd = allResolvedRows.reduce(
        (highest, row) => Math.max(highest, Number(row.ord) || 0),
        priorCursor ?? 0,
      );

      // Reconcile only rows the browser was already tracking. Feeding every
      // historical `opened` purchase into the tray is what produced dozens of
      // phantom OPEN notifications on a fresh browser.
      for (const key of tracked) {
        if (revealed.has(key)) {
          local.delete(key);
          continue;
        }
        const prior = local.get(key);
        const feed = Number(prior?.index) > 0 ? feedRows.get(Number(prior.index)) : null;
        const settled = resolvedByKey.get(key);
        if (settled) {
          local.set(key, {
            ...prior,
            ...settled,
            transactionHashes: [...new Set([
              ...(Array.isArray(prior?.transactionHashes) ? prior.transactionHashes : []),
              ...(Array.isArray(feed?.transactionHashes) ? feed.transactionHashes : []),
            ].filter(Boolean).map((hash) => String(hash).toLowerCase()))],
            amountWei: _firstPositiveAmount(
              feed?.amountWei,
              settled.rawPurchaseAmountWei,
              prior?.amountWei,
              settled.amountWei,
            ),
            hasLootboxLeg: Boolean(
              prior?.hasLootboxLeg || feed?.hasLootboxLeg || settled.hasLootboxLeg,
            ),
            ready: true,
            resolved: true,
            resultSyncing: false,
          });
        } else if (feed) {
          local.set(key, {
            ...prior,
            transactionHash: prior?.transactionHash ?? feed.transactionHash,
            transactionHashes: [...new Set([
              ...(Array.isArray(prior?.transactionHashes) ? prior.transactionHashes : []),
              prior?.transactionHash,
              ...(Array.isArray(feed.transactionHashes) ? feed.transactionHashes : []),
              feed.transactionHash,
            ].filter(Boolean).map((hash) => String(hash).toLowerCase()))],
            amountWei: BigInt(feed.amountWei ?? 0) > 0n
              ? feed.amountWei
              : prior?.amountWei,
            hasLootboxLeg: Boolean(prior?.hasLootboxLeg || feed.hasLootboxLeg),
            ready: Boolean(feed.ready),
            resolved: Boolean(feed.resolved),
          });
        }
      }

      // First visit establishes a history baseline without reviving an old
      // opening. Tracked purchases still reconcile above. After that, every
      // result newer than the durable cursor is kept,
      // so several boxes settling between polls cannot collapse into one chip.
      const discovered = newlyDiscoveredRows.filter(
        (row) => !degeneretteChildKeys.has(_boxKey(row)),
      );
      for (const settled of discovered) {
        const key = _boxKey(settled);
        if (!key || revealed.has(key)) continue;
        const prior = local.get(key);
        const feed = Number(settled.index) > 0 ? feedRows.get(Number(settled.index)) : null;
        local.set(key, {
          ...prior,
          ...settled,
          transactionHashes: [...new Set([
            ...(Array.isArray(prior?.transactionHashes) ? prior.transactionHashes : []),
            ...(Array.isArray(feed?.transactionHashes) ? feed.transactionHashes : []),
          ].filter(Boolean).map((hash) => String(hash).toLowerCase()))],
          amountWei: _firstPositiveAmount(
            feed?.amountWei,
            settled.rawPurchaseAmountWei,
            prior?.amountWei,
            settled.amountWei,
          ),
          hasLootboxLeg: Boolean(
            prior?.hasLootboxLeg || feed?.hasLootboxLeg || settled.hasLootboxLeg,
          ),
          ready: true,
          resolved: true,
          resultSyncing: false,
          opening: false,
          fromReceipt: Boolean(prior?.fromReceipt),
        });
      }
      if (legsCall.status === 'fulfilled') _writeResultCursor(owner, newestOrd);

      // Unresolved DB purchases are only candidates. `opened:false` is not
      // authoritative for legacy rows whose settlement event lacked an index.
      // Only a local purchase receipt or an exact successful open simulation
      // proves that this player still owns an actionable box.
      const candidates = new Map(
        [...local.values()]
          .filter((box) => !box.resolved && Number(box.index) > 0)
          .map((box) => [_boxKey(box), box]),
      );
      for (const row of feedRows.values()) {
        if (row.resolved
          || revealed.has(String(row.index))
          || this.#emptyIndexes.has(row.index)) continue;
        const key = String(row.index);
        if (!candidates.has(key)) candidates.set(key, { ...row, resultKey: key });
      }

      const probes = [...candidates.values()];
      const probeResults = await Promise.allSettled(probes.map(async (box) => {
        const completion = await readLootboxIndexCompletion(box.index);
        let hasLootboxLeg = Boolean(box.hasLootboxLeg);
        let receiptAmountWei = null;
        const purchaseHashes = [
          ...(Array.isArray(box?.transactionHashes) ? box.transactionHashes : []),
          box?.transactionHash,
        ].filter(Boolean);
        // A swept, DB-only candidate is discarded below. Recovering its old
        // purchase kind cannot change that decision and can hit multiple RPCs
        // when an endpoint no longer has the receipt. Keep recovery for local
        // receipt-backed purchases: they still wait for their result legs.
        if (purchaseHashes.length > 0 && (completion !== true || box.fromReceipt)) {
          const purchase = await this.#readPurchaseKinds(box, owner);
          if (purchase) {
            hasLootboxLeg ||= purchase.hasLootboxLeg;
            receiptAmountWei = String(purchase.amountWei);
          }
        }
        let chainReady = false;
        // A sweep that stops mid-index settles THIS player's entry while the
        // index stays incomplete, so NothingToClaim (the zeroed entry) is the
        // only read that proves the slot is gone. Without it the row kept failing the
        // readiness probe and re-rendering as "waiting for RNG" forever.
        let chainSettled = false;
        // Re-probe a box that has actually failed. `ready` used to latch: once
        // true it was never checked again, so a box the chain had stopped
        // accepting stayed armed forever and every click failed the same way.
        // Unverified DB rows must also pass the exact-player simulation before
        // they can create a notification.
        const suspect = Number(box.openFailures) > 0;
        const receiptBacked = Boolean(box.fromReceipt);
        if (completion !== true && (!receiptBacked || !box.ready || suspect)) {
          const probe = await probeOpenLootbox({
            player: owner,
            lootboxIndex: box.index,
          }).catch(() => ({ ok: false, settled: false }));
          chainReady = Boolean(probe.ok);
          chainSettled = Boolean(probe.settled);
        }
        const settled = completion === true || chainSettled;
        return {
          key: _boxKey(box),
          index: box.index,
          candidate: box,
          completionKnown: completion != null || chainSettled,
          complete: settled,
          chainReady,
          hasLootboxLeg,
          receiptAmountWei,
          ready: !settled && (
            receiptBacked && !suspect ? Boolean(box.ready || chainReady) : chainReady
          ),
        };
      }));
      if (this.#addr !== owner || token !== this.#workToken()) return;
      for (const result of probeResults) {
        if (result.status !== 'fulfilled') continue;
        const {
          key, index, candidate, completionKnown, complete, chainReady, ready,
          hasLootboxLeg, receiptAmountWei,
        } = result.value;
        const prior = local.get(key);
        const receiptBacked = Boolean(prior?.fromReceipt);
        if (!completionKnown && !receiptBacked && !chainReady) {
          // A receipt row survives an RPC blip; an unverified DB-history row
          // never earns a notification from unavailable chain reads.
          local.delete(key);
          continue;
        }
        if (complete && !chainReady) {
          if (receiptBacked) {
            // Completion proves the entire index was swept. Keep the durable
            // purchase receipt while its immutable result legs catch up.
            local.set(key, {
              ...candidate,
              ...prior,
              ready: false,
              resolved: true,
              resultSyncing: true,
              opening: false,
              amountWei: _firstPositiveAmount(
                prior?.amountWei,
                receiptAmountWei,
                candidate?.amountWei,
              ),
            });
          } else {
            local.delete(key);
            this.#emptyIndexes.add(index);
          }
          continue;
        }
        if (!receiptBacked && !chainReady) {
          // An incomplete index is ambiguous: this row may be waiting for RNG,
          // already settled while another player's box remains, or stale DB
          // history. Do not invent a player box without receipt evidence.
          local.delete(key);
          continue;
        }
        local.set(key, {
          ...candidate,
          ...prior,
          ready,
          resolved: false,
          resultSyncing: false,
          amountWei: _firstPositiveAmount(
            prior?.amountWei,
            receiptAmountWei,
            candidate?.amountWei,
          ),
          opening: Boolean(prior?.opening),
          fromReceipt: receiptBacked,
          hasLootboxLeg,
        });
      }

      if (token !== this.#workToken()) return;
      // Completion can arrive while this snapshot waits on another box's RPC.
      // Re-read the durable markers at commit time and honor foreground removals
      // even when browser storage is unavailable. Never resurrect their old
      // `opening` flag after the reveal has released its active key.
      const latestRevealed = _readRevealed(owner);
      const currentKeys = new Set(this.#boxes.map(_boxKey));
      this.#boxes = [...local.values()].filter((box) => {
        const key = _boxKey(box);
        return !latestRevealed.has(key) && (!tracked.has(key) || currentKeys.has(key));
      }).sort((a, b) => (
        (Number(b.ord) || 0) - (Number(a.ord) || 0)
        || Number(b.index) - Number(a.index)
      ));
      await this.#refreshSyncingResults(owner);
      if (this.#addr !== owner || token !== this.#workToken()) return;
      _writePending(owner, this.#boxes);
      this.#render();
      // One prefetch walk at a time; a poll that lands mid-walk leaves the rest to it.
      if (!this.#prefetchInFlight) {
        this.#prefetchInFlight = this.#prefetchResolvedResults(owner)
          .catch(() => {})
          .finally(() => { this.#prefetchInFlight = null; });
      }
    } catch (_e) {
      // API/indexer blip — keep the last honest state and retry next tick.
    } finally {
      this.#pollBusy = false;
      this.#pollInFlight = null;
      settle();
    }
  }

  async #refreshSyncingResults(owner) {
    const token = this.#workToken();
    const syncing = this.#boxes.filter((box) => (
      box.resolved
      && box.resultSyncing
      && !this.#activeRevealKeys.has(_boxKey(box))
    ));
    if (syncing.length === 0) return;

    // A settled slot is no longer an action the wallet can perform. Poll for
    // its immutable result in the background and promote it exactly once when
    // a complete replay is available; never make Auto retry the same miss.
    for (const box of syncing) box.ready = false;
    const recovered = await Promise.allSettled(syncing.map(async (box) => ({
      key: _boxKey(box),
      result: await this.#readResolvedBoxResult(box),
    })));
    if (this.#addr !== owner || token !== this.#workToken()) return;
    for (const result of recovered) {
      if (result.status !== 'fulfilled' || result.value.result.legs.length === 0) continue;
      const box = this.#boxes.find((candidate) => _boxKey(candidate) === result.value.key);
      if (!box) continue;
      const resultHash = result.value.result.legs
        .find((leg) => leg?.transactionHash)?.transactionHash;
      if (resultHash) box.resultTransactionHash = String(resultHash).toLowerCase();
      box.ready = true;
      box.resultSyncing = false;
    }
  }

  // -------------------------------------------------------------------------
  // Open click → mineFlip tx → this box's legs → reveal overlay.
  // -------------------------------------------------------------------------

  async #onOpenClick(box) {
    if (box.opening || !box.ready) return false;
    const token = this.#workToken();
    box.opening = true;
    this.#render();
    this.#clearError();
    try {
      if (box.resolved) {
        return (await this.#replayResolvedBox(box)) === 'revealed';
      }
      // An indexer can learn about a settlement between polling cycles (or
      // while the connected RPC is still serving the pre-settlement block), so
      // API mode prefers that immutable result before the exact write probe. In
      // chain mode the leg feed IS the probe's RPC and cannot know more: the
      // probe goes first, and a settled answer replays below.
      if (CHAIN.readMode !== 'chain') {
        const indexedReplay = await this.#replayResolvedBox(box, { silentIfMissing: true });
        if (token !== this.#workToken()) return false;
        if (indexedReplay !== 'missing') return indexedReplay === 'revealed';
      }
      // Never open from a stale UI snapshot. This exact-player static call is
      // the only current GAME read that proves the box is ready and pending.
      const probe = await probeOpenLootbox({
        player: this.#addr,
        lootboxIndex: box.index,
      }).catch(() => ({ ok: false, settled: false }));
      if (token !== this.#workToken()) return false;
      if (!probe.ok) {
        // Of the probe's reasons only NothingToClaim means "this player's boxes
        // at this index are already resolved". The sweep frontier alone cannot
        // see that: a sweep that spent its budget mid-index leaves
        // boxIndexComplete false
        // indefinitely, so a settled box used to fall back to the RNG wait it
        // had already cleared and could never leave — it stopped opening for
        // good. Trust the revert reason first, the frontier only as a fallback.
        const complete = probe.settled
          ? true
          : await readLootboxIndexCompletion(box.index);
        if (token !== this.#workToken()) return false;
        const settled = complete === true;
        if (settled && CHAIN.readMode === 'chain') {
          // Opened since the last poll: replay it now rather than send the
          // player back to wait for the next cycle.
          const replay = await this.#replayResolvedBox(box, { silentIfMissing: true });
          if (token !== this.#workToken()) return false;
          if (replay !== 'missing') return replay === 'revealed';
        }
        box.opening = false;
        box.ready = false;
        box.resolved = settled;
        box.resultSyncing = settled;
        if (this.#addr) _writePending(this.#addr, this.#boxes);
        this.#render();
        if (settled) void this.#runPollCycle();
        return false;
      }

      const { receipt, opened } = await openLootBox({
        player: this.#addr,
        lootboxIndex: box.index,
      });
      if (token !== this.#workToken()) return false;
      if (opened === false) {
        // Audit 2525eb7fd: the only manual door is the in-order sweep, and this
        // call's budget ran out on the boxes queued ahead of this one. It stays
        // armed; the next OPEN (or any mineFlip crank) continues from there.
        box.opening = false;
        this.#renderError('Opened the boxes ahead of yours. Tap OPEN again to reach it.');
        this.#render();
        return false;
      }
      const settlementHash = receipt?.hash || receipt?.transactionHash || null;
      let legs = parseOpenLegsFromReceipt(receipt, this.#addr, { includeRecordBounties: false });
      // One sweep can open this player's boxes at several indices. The receipt's
      // legs are this box's only when every opening anchor in it names this index;
      // otherwise assemble them by index, exactly as for a keeper-settled box.
      const anchors = new Set(legs
        .filter((leg) => leg?.lootboxIndex != null)
        .map((leg) => String(leg.lootboxIndex)));
      if (opened === true && !(anchors.size === 1 && anchors.has(String(box.index)))) {
        // Not pinned to this sweep's hash: a competing sweep may be the one that
        // opened the entry before this one mined.
        const replay = await this.#replayResolvedBox(box, { silentIfMissing: true });
        if (token !== this.#workToken()) return false;
        if (replay !== 'missing') return replay === 'revealed';
        // Opened, legs still indexing: passive sync, never another write.
        box.opening = false;
        box.ready = false;
        box.resolved = true;
        box.resultSyncing = true;
        if (this.#addr) _writePending(this.#addr, this.#boxes);
        this.#render();
        void this.#runPollCycle();
        return false;
      }
      legs = await enrichHumanBoxSpinLegs(legs, {
        player: this.#addr,
        lootboxIndex: box.index,
        blockNumber: receipt?.blockNumber ?? null,
      });
      legs = await enrichLootboxBoonLegs(legs, {
        player: this.#addr,
        lootboxIndex: box.index,
        blockNumber: receipt?.blockNumber ?? null,
      });
      if (token !== this.#workToken()) return false;
      if (lootboxResultLegsReadyForReveal(legs)) {
        box.resultTransactionHash = settlementHash || box.resultTransactionHash || null;
        box.transactionHash = settlementHash || box.transactionHash || null;
        return this.#queueBoxReveal(box, legs);
      } else {
        // The transaction landed, but its prize legs are either omitted or
        // newer than this client's result ABI. A bare opened anchor is not
        // a zero-result card. Persist the settlement hash and let background
        // recovery assemble a concrete reveal; this is no longer an open
        // action and must not be auto-clicked every polling interval.
        box.resultTransactionHash = settlementHash || box.resultTransactionHash || null;
        box.opening = false;
        box.ready = false;
        box.resolved = true;
        box.resultSyncing = true;
        if (this.#addr) _writePending(this.#addr, this.#boxes);
        this.#render();
        void this.#runPollCycle();
        return false;
      }
    } catch (error) {
      if (token !== this.#workToken()) return false;
      box.opening = false;
      const failureMessage = compactUiError(error, 'Box did not open. Try again.');

      // A cancelled wallet prompt did not race an on-chain opener. Keep the
      // exact box armed so the player can deliberately try it again.
      if (failureMessage === 'Transaction cancelled.') {
        box.openFailures = Math.max(0, Number(box.openFailures) || 0) + 1;
        this.#renderError(failureMessage);
        this.#render();
        return false;
      }

      const revertName = openBoxRevertName(error);
      if (revertName === 'RngNotReady' || revertName === 'RngLocked') {
        // The readiness window closed between the two exact pre-flights. Return
        // to passive RNG polling instead of retrying the same doomed write.
        box.ready = false;
        box.resolved = false;
        box.resultSyncing = false;
        box.openFailures = Math.max(0, Number(box.openFailures) || 0) + 1;
        if (this.#addr) _writePending(this.#addr, this.#boxes);
        this.#render();
        void this.#runPollCycle();
        return false;
      }

      // The box passed the exact-player readiness probe immediately before the
      // write. A non-cancellation failure at that point is the permissionless
      // opener race: another wallet settled it first. Ask the same immutable
      // result feed used by background discovery before waiting for indexing;
      // never publish another open action for this already-credited box.
      const indexedReplay = await this.#replayResolvedBox(box, { silentIfMissing: true });
      if (token !== this.#workToken()) return false;
      if (indexedReplay !== 'missing') return indexedReplay === 'revealed';
      box.ready = false;
      box.resolved = true;
      box.resultSyncing = true;
      if (this.#addr) _writePending(this.#addr, this.#boxes);
      this.#render();
      void this.#runPollCycle();
      return false;
    }
  }

  #clearResultReads() {
    this.#resolvedLegCache.clear();
    this.#resolvedLegReads.clear();
    this.#prefetchAttemptAt.clear();
    this.#recentLegRows = { owner: null, items: [] };
  }

  // A pending box the chain has already opened (a keeper sweep, another wallet, an
  // earlier session) has a final result. Assemble it while the box waits in Pending
  // so OPEN replays it at once instead of loading it after the click. One box at a
  // time: this runs beside the poll, on the same public RPC.
  async #prefetchResolvedResults(owner) {
    const token = this.#workToken();
    const now = Date.now();
    const due = this.#boxes.filter((box) => {
      const key = _boxKey(box);
      return key
        && box.resolved && box.ready && !box.resultSyncing && !box.opening
        && !this.#activeRevealKeys.has(key)
        && !this.#resolvedLegCache.has(key)
        && !this.#resolvedLegReads.has(key)
        && now - (this.#prefetchAttemptAt.get(key) ?? 0) >= RESULT_PREFETCH_RETRY_MS;
    });
    for (const box of due) {
      if (this.#addr !== owner || token !== this.#workToken()) return;
      this.#prefetchAttemptAt.set(_boxKey(box), Date.now());
      try { await this.#readResolvedBoxResult(box); } catch (_e) { /* OPEN reads it again */ }
    }
  }

  #readResolvedBoxResult(box) {
    const key = _boxKey(box);
    const inFlight = key ? this.#resolvedLegReads.get(key) : null;
    if (inFlight) return inFlight;
    const read = this.#assembleResolvedBoxResult(box);
    if (!key) return read;
    this.#resolvedLegReads.set(key, read);
    const release = () => {
      if (this.#resolvedLegReads.get(key) === read) this.#resolvedLegReads.delete(key);
    };
    read.then(release, release);
    return read;
  }

  async #assembleResolvedBoxResult(box) {
    const token = this.#workToken();
    const key = _boxKey(box);
    const cached = this.#resolvedLegCache.get(key);
    if (Array.isArray(cached) && cached.length > 0) {
      return { legs: cached, settled: true };
    }
    const legOptions = {
      player: this.#addr,
      lootboxIndex: box.index,
      // Prefer the settlement hash recorded when the leg feed proved this box
      // was opened (resolvedBoxRowsFromLegs). Discarding it and re-deriving an
      // anchor by index is what let the two matching rules disagree: the poll
      // marked the box resolved, this lookup found no anchor, and the box
      // latched resolved with nothing to replay. Falling back to
      // `box.transactionHash` only for index zero preserves the old behaviour
      // for receipt-discovered boxes, where that hash IS the purchase.
      transactionHash: box.resultTransactionHash
        || (Number(box.index) === 0 ? box.transactionHash : null),
    };
    let legs = [];
    // Chain mode serves both the exact-index and the recent lookup from the same
    // 200-row window of the same RPC the poll just read, so its rows already hold
    // every leg either lookup could find. An API can filter by index server-side
    // past that window, so it keeps the exact request.
    const recent = this.#recentLegRows;
    if (CHAIN.readMode === 'chain' && recent.owner === this.#addr && recent.items.length > 0) {
      legs = openLegsFromFeed(recent.items, legOptions);
      if (_missingBoxes(box, legs)) legs = [];
    }
    if (legs.length === 0) {
      try {
        // Ask for both the exact index and the player's newest legs. Current APIs
        // attach the opening index to every same-transaction leg; older deployed
        // APIs leave BoxSpin.index null and only the unfiltered player page can
        // carry those reels. Merging both shapes preserves every spin.
        const base = `/lootbox/legs?limit=200&player=${encodeURIComponent(this.#addr)}`;
        const [exactCall, recentCall] = await Promise.allSettled([
          // This exact row is the settlement catch-up probe. The prior empty
          // result is precisely what put the box in resultSyncing, so it must not
          // be reused from the short render cache on the next recovery cycle.
          fetchJSON(
            `${base}&lootboxIndex=${encodeURIComponent(box.index)}`,
            { force: true },
          ),
          fetchJSON(base),
        ]);
        const rows = _mergeLegRows(
          exactCall.status === 'fulfilled' ? exactCall.value?.items : [],
          recentCall.status === 'fulfilled' ? recentCall.value?.items : [],
        );
        legs = openLegsFromFeed(rows, legOptions);
      } catch (_e) {
        // Fall through to the exact chain-event replay below.
      }
    }
    if ((_needsReceiptRecovery(legs) || _missingBoxes(box, legs)) && Number(box.index) > 0) {
      try {
        const receiptLegs = await readOpenLegsFromChain({
          player: this.#addr,
          lootboxIndex: box.index,
          boxAmountWei: box.amountWei,
          boxOrders: _boxOrders(box.boxOrders, box.boxOrder),
          ticketPriceWei: box.ticketPriceWei,
          purchaseTransactionHashes: [
            box.resultTransactionHash,
            ...(Array.isArray(box.transactionHashes) ? box.transactionHashes : []),
            box.transactionHash,
          ].filter(Boolean),
        });
        if (receiptLegs.length > 0
          && (!_missingBoxes(box, receiptLegs) || _settledBoxCount(receiptLegs) > _settledBoxCount(legs))) {
          legs = receiptLegs;
        }
      } catch (_e) {
        // Let indexed legs continue through enrichment and the completeness
        // boundary below. A concrete prize is usable; a bare anchor stays in
        // passive sync until its companion projection or receipt becomes available.
      }
    }

    const settlementBlockNumber = box.blockNumber
      ?? legs.find((leg) => leg?.blockNumber != null)?.blockNumber
      ?? null;
    legs = await enrichHumanBoxSpinLegs(legs, {
      player: this.#addr,
      lootboxIndex: box.index,
      blockNumber: settlementBlockNumber,
    });
    legs = await enrichLootboxBoonLegs(legs, {
      player: this.#addr,
      lootboxIndex: box.index,
      blockNumber: settlementBlockNumber,
    });
    if (token !== this.#workToken()) return { legs: [], settled: false };
    const settled = legs.length > 0;
    // Settled but short: stay in passive sync and read again next cycle.
    if (_missingBoxes(box, legs)) {
      const since = this.#shortResultSince.get(key) ?? Date.now();
      this.#shortResultSince.set(key, since);
      if (Date.now() - since < SHORT_RESULT_GRACE_MS) return { legs: [], settled };
    }
    this.#shortResultSince.delete(key);
    if (!lootboxResultLegsReadyForReveal(legs)) return { legs: [], settled };
    if (key && legs.length > 0) this.#resolvedLegCache.set(key, legs);
    return { legs, settled: true };
  }

  async #replayResolvedBox(box, {
    silentIfMissing = false,
  } = {}) {
    const token = this.#workToken();
    const { legs, settled } = await this.#readResolvedBoxResult(box);
    if (token !== this.#workToken()) return 'cleared';
    if (legs.length > 0) {
      const accepted = this.#queueBoxReveal(box, legs, { settledExpected: true });
      if (!accepted) {
        // A matching presentation is already queued or was shown this session.
        // The indexed legs still prove settlement, so retire this duplicate
        // action instead of falling through to an impossible wallet write.
        const address = this.#addr;
        const key = _boxKey(box);
        if (address && key) _markRevealed(address, key);
        if (key) this.#removeBox(key);
      }
      return 'revealed';
    }

    if (settled) {
      // The immutable anchor wins over a potentially stale RPC slot, but it is
      // not displayable until a complete result projection is available.
      // Preserve the pending receipt and never offer another wallet write.
      box.opening = false;
      box.ready = false;
      box.resolved = true;
      box.resultSyncing = true;
      if (this.#addr) _writePending(this.#addr, this.#boxes);
      this.#render();
      void this.#runPollCycle();
      return 'syncing';
    }

    // Probe mode is used immediately before a write. A miss simply continues
    // to the exact-player readiness check without changing the busy state.
    if (silentIfMissing) return 'missing';

    // A miss here used to unconditionally re-arm `ready + resolved`, which put
    // the box straight back into this same branch on the next click: a silent
    // loop that never opened and never gave up, because `resultSyncing`
    // suppresses the error toast. Ask the chain what is actually true before
    // deciding whether waiting is even the right thing to do.
    box.opening = false;
    const actionable = await canOpenLootbox({
      player: this.#addr,
      lootboxIndex: box.index,
    }).catch(() => false);

    if (actionable) {
      // The exact write still succeeds, so the box is NOT settled and there are
      // no legs to replay. Hand it back to the normal open path.
      box.resolved = false;
      box.resultSyncing = false;
      this.#resolvedLegCache.delete(_boxKey(box));
      if (this.#addr) _writePending(this.#addr, this.#boxes);
      this.#render();
      return 'missing';
    }

    // Settled on chain, legs still indexing. This is passive synchronization,
    // not a repeatable player action: disarm the row and let the normal poll
    // promote it once a complete result is available.
    box.ready = false;
    box.resolved = true;
    box.resultSyncing = true;
    if (this.#addr) _writePending(this.#addr, this.#boxes);
    this.#render();
    return 'syncing';
  }

  #boxRevealSequence(box, legs, { title = null, settledExpected = false } = {}) {
    const address = this.#addr;
    const key = _boxKey(box);
    if (!address || !key || !Array.isArray(legs) || legs.length === 0) return false;
    const ticketPackRelease = lootboxTicketPackRelease({
      address,
      legs,
      sourceKey: `lootbox:${key}`,
      settledExpected,
    });
    return {
      kind: 'lootbox',
      ...(title ? { title } : {}),
      lootboxIndex: box.index,
      amountWei: _boxDisplayAmount(box),
      ticketPriceWei: box.ticketPriceWei,
      boxOrders: _boxOrders(box.boxOrders, box.boxOrder),
      legs,
      settledExpected,
      ...(ticketPackRelease ? { ticketPackRelease } : {}),
      lootboxRelease: {
        address,
        key,
        lootboxIndex: Number(box.index),
        transactionHash: box.transactionHash || null,
      },
    };
  }

  #queueBoxReveal(box, legs, options = {}) {
    const address = this.#addr;
    const key = _boxKey(box);
    const accepted = queueReveal(this.#boxRevealSequence(box, legs, options));
    if (!accepted) return false;
    // Hide the action while its presentation is active, but keep its durable
    // receipt until completion. If the overlay aborts or the page reloads, the
    // player gets the result action back instead of losing it from Pending.
    // The indexed legs are now in hand, so an aborted presentation is a normal
    // "View result" retry instead of falling back to the stale syncing label.
    box.resultSyncing = false;
    this.#activeRevealKeys.add(key);
    box.opening = true;
    _writePending(address, this.#boxes);
    this.#render();
    return true;
  }

  #removeBox(keyOrIndex) {
    const key = String(keyOrIndex);
    this.#activeRevealKeys.delete(key);
    this.#resolvedLegCache.delete(key);
    this.#boxes = this.#boxes.filter((box) => _boxKey(box) !== key);
    if (this.#addr) _writePending(this.#addr, this.#boxes);
    this.#render();
  }

  #clearAllBoxes() {
    const address = this.#addr;
    if (!address) return false;
    this.#clearGeneration += 1;
    // CLEAR is presentation-only. Mark every tracked result as seen so the
    // database discovery pass does not recreate the same notification after a
    // refresh; any unopened box and all of its rewards remain untouched on
    // chain and can still be resolved permissionlessly later.
    for (const box of this.#boxes) {
      const key = _boxKey(box);
      if (key) _markRevealed(address, key);
    }
    this.#boxes = [];
    this.#activeRevealKeys.clear();
    this.#clearResultReads();
    _writePending(address, this.#boxes);
    this.#render();
    return true;
  }

  // -------------------------------------------------------------------------
  // Render — chips via createElement (T-58-18).
  // -------------------------------------------------------------------------

  #publishPending() {
    if (!this.#addr) {
      clearPendingActions(PENDING_SOURCE);
      return;
    }
    const visibleBoxes = this.#boxes.filter((box) => !this.#activeRevealKeys.has(_boxKey(box)));
    publishPendingActions(PENDING_SOURCE, visibleBoxes.map((box) => {
      const value = _boxValuePresentation(box);
      const resultSyncing = Boolean(box.resolved && box.resultSyncing);
      return {
      id: `lootbox:${_boxKey(box)}`,
      dismissScope: this.#addr,
      // Several buys can share one live RNG index. Version the presentation
      // tombstone by its mined purchase receipts so clearing an older box does
      // not hide a later pass purchase in the same batch.
      dismissKey: _boxDismissKey(box),
      kind: 'lootbox',
      mayAddEth: Boolean(box.resolved),
      amountWei: String(_boxDisplayAmount(box)),
      amountLabel: _boxAmountLabel(box),
      ticketPriceWei: value.ticketPriceWei == null ? null : String(value.ticketPriceWei),
      lootboxValueTone: value.tone,
      lootboxCaseModel: value.model,
      lootboxTicketUnitsLabel: value.unitsLabel,
      lootboxStacks: _boxStacks(box),
      label: _boxLabel(box),
      lootboxLabel: _boxLabel(box, true),
      shortLabel: box.optimistic
        ? 'Transaction sent'
        : box.index == null
          ? 'Syncing purchase'
          : resultSyncing ? 'Syncing result' : box.resolved ? 'View result' : 'Open box',
      detail: box.optimistic
        ? 'Purchase sent · waiting for confirmation'
        : box.index == null
          ? 'Purchase confirmed · syncing RNG queue'
        : resultSyncing
          ? 'Settlement confirmed · loading the reveal receipt'
        : box.opening
        ? box.resolved ? 'Loading indexed result' : 'Opening on-chain'
        : box.ready
          ? box.resolved ? 'Result indexed · ready to replay' : 'RNG ready · prizes locked'
          : `Waiting for RNG${box.day == null ? '' : ` · Day ${box.day}`}`,
      state: box.opening ? 'busy' : resultSyncing ? 'waiting' : box.ready ? 'ready' : 'waiting',
      // Normal purchased boxes and Degenerette share the mid-day Chainlink
      // batch. Publishing that relationship explicitly lets the permanent RNG
      // widget appear on the receipt paint, inherit the real queue fill, and
      // become the request control without waiting for the indexer.
      sharedRng: !box.optimistic,
      phase: box.optimistic
        ? 'submitting'
        : resultSyncing ? 'indexing' : box.opening ? 'resolving' : box.ready ? 'result-ready' : 'awaitingRng',
      // Pending/RNG-ready boxes cannot spoil a payout that does not exist yet.
      // Consumers may gate balances only after an indexed settlement exists.
      resolved: Boolean(box.resolved),
      pinned: true,
      // Readiness changes what clicking the receipt does, not its shape. The
      // compact amount + box-glyph label remains the entire open target.
      compact: true,
      progress: resultSyncing || (!box.ready && !box.opening) ? 'indeterminate' : null,
      write: !box.resolved,
      // A resolved/indexed box only replays its popup. An unresolved ready box
      // still needs an explicit mineFlip wallet transaction and is never run by
      // the tray's OPEN WHEN READY preference.
      autoOpen: Boolean(box.resolved && box.ready && !box.opening && !resultSyncing),
      order: 20,
      chronology: Number.isFinite(Number(box.createdAt))
        ? Number(box.createdAt)
        : Number.isFinite(Number(box.ord)) ? Number(box.ord) : Number(box.index),
      prepareKey: `${box.resolved}:${box.resultTransactionHash || box.transactionHash || ''}`,
      prepare: async () => {
        if (!box.resolved || !box.ready) return;
        const { legs, settled } = await this.#readResolvedBoxResult(box);
        if (!settled || !legs?.length) return false;
        await prepareReveal(this.#boxRevealSequence(box, legs, { settledExpected: true }));
      },
      run: () => this.#onOpenClick(box),
      clearAll: () => this.#clearAllBoxes(),
      };
    }));
  }

  #render() {
    this.#publishPending();
    const strip = this.#bind('bxs-strip');
    const chips = this.#bind('bxs-chips');
    if (!strip || !chips) return;
    const visibleBoxes = this.#boxes.filter((box) => !this.#activeRevealKeys.has(_boxKey(box)));
    const show = Boolean(this.#addr) && visibleBoxes.length > 0;
    strip.hidden = !show;
    chips.textContent = '';
    if (!show) return;
    for (const box of visibleBoxes) {
      const value = _boxValuePresentation(box);
      const chip = document.createElement('div');
      chip.className = `bxs-chip${box.ready ? ' bxs-chip--ready' : ''}`
        + (box.opening ? ' bxs-chip--opening' : '');
      chip.setAttribute('data-lootbox-value-tone', value.tone);
      applyLootboxCasePresentation(chip, value.model);
      if (value.unitsLabel && !/^1\s*[×x]$/i.test(String(value.unitsLabel).trim())) {
        chip.title = `${value.unitsLabel} ticket-price box`;
      }

      const art = document.createElement('span');
      art.className = 'bxs-chip-art';
      art.setAttribute('data-lootbox-value-tone', value.tone);
      applyLootboxCasePresentation(art, value.model);
      chip.appendChild(art);

      const copy = document.createElement('span');
      copy.className = 'bxs-chip-copy';
      const amountLabel = _boxAmountLabel(box);
      if (amountLabel) {
        const amount = document.createElement('span');
        amount.className = 'bxs-chip-amount';
        amount.textContent = amountLabel;
        copy.appendChild(amount);
      }
      const title = document.createElement('strong');
      title.className = 'bxs-chip-title';
      title.textContent = _boxLabel(box, true);
      copy.appendChild(title);
      chip.appendChild(copy);

      const cta = document.createElement('button');
      cta.type = 'button';
      cta.className = 'bxs-open-cta';
      if (!box.resolved) cta.setAttribute('data-write', '');
      cta.disabled = !box.ready || box.opening;
      cta.textContent = box.opening
        ? 'OPENING…'
        : box.ready ? box.resolved ? 'VIEW RESULT' : `OPEN ${_boxLabel(box, true)}` : 'RNG PENDING';
      cta.setAttribute('aria-label', box.ready
        ? Number(box.index) > 0
          ? `${box.resolved ? 'View result for' : 'Open'} luckbox ${box.index}`
          : `${box.resolved ? 'View result for' : 'Open'} luckbox`
        : `${_boxLabel(box)} waiting for RNG`);
      if (box.ready && !box.opening) {
        cta.addEventListener('click', () => this.#onOpenClick(box));
      }
      chip.appendChild(cta);
      chips.appendChild(chip);
    }
  }

  /** Test-only: land one tracked box without an RPC. */
  __setReadyForTest(index) {
    const box = this.#boxes.find((item) => item.index === Number(index));
    if (!box) return false;
    box.ready = true;
    this.#render();
    return true;
  }

  /**
   * Test-only deterministic polling seam. Drains the cycle the connect/address
   * subscription may already have started before running a guaranteed fresh
   * one, so a caller never asserts against a half-applied poll.
   */
  async __pollForTest() {
    await this.#pollInFlight;
    await this.#runPollCycle();
    await this.#prefetchInFlight;
  }

  #renderError(msg) {
    const errEl = this.#bind('bxs-error');
    if (!errEl) {
      // Production mounts this controller in tray-only mode. Route failures to
      // the one visible Pending surface instead of swallowing them in an
      // inline error node that does not exist there.
      reportPendingActionError(msg);
      return;
    }
    errEl.textContent = String(msg);
    errEl.hidden = false;
    if (this.#errorTimer != null) {
      try { clearTimeout(this.#errorTimer); } catch (_) { /* defensive */ }
    }
    this.#errorTimer = setTimeout(() => this.#clearError(), ERROR_AUTO_CLEAR_MS);
    if (this.#errorTimer && typeof this.#errorTimer.unref === 'function') {
      try { this.#errorTimer.unref(); } catch (_) { /* defensive */ }
    }
  }

  #clearError() {
    const errEl = this.#bind('bxs-error');
    if (errEl) {
      errEl.textContent = '';
      errEl.hidden = true;
    }
    if (this.#errorTimer != null) {
      try { clearTimeout(this.#errorTimer); } catch (_) { /* defensive */ }
      this.#errorTimer = null;
    }
  }
}

if (typeof customElements !== 'undefined' && typeof customElements.define === 'function') {
  if (!customElements.get('app-box-strip')) {
    customElements.define('app-box-strip', AppBoxStrip);
  }
}

export { AppBoxStrip };
